function validate([n, languages, friendships]) {
  if (!Number.isInteger(n) || n < 2 || n > 500) return 'n must be a whole number from 2 to 500.';
  const m = languages.length;
  if (m < 1 || m > 500) return 'There must be 1 to 500 users.';
  for (const list of languages) {
    if (!Array.isArray(list) || list.length < 1 || list.length > n) return 'Each user speaks 1 to n languages.';
    if (list.some(x => !Number.isInteger(x) || x < 1 || x > n)) return 'Languages are numbered 1 to n.';
    if (new Set(list).size !== list.length) return 'A user lists each language once.';
  }
  if (friendships.length < 1 || friendships.length > 500) return 'There must be 1 to 500 friendships.';
  const seen = new Set();
  for (const pair of friendships) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each friendship is a pair [u, v].';
    const [u, v] = pair;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || u >= v || v > m) return 'Each friendship needs 1 <= u < v <= m.';
    if (seen.has(u * 1000 + v)) return 'Friendships must be distinct.';
    seen.add(u * 1000 + v);
  }
  return null;
}

