function minimumTeachings(n, languages, friendships) {
  const known = languages.map(list => new Set(list));
  const stuck = new Set();

  for (const [u, v] of friendships) {
    let shared = false;
    for (const lang of known[u - 1]) {
      if (known[v - 1].has(lang)) {
        shared = true;
        break;
      }
    }
    if (!shared) {
      stuck.add(u - 1);
      stuck.add(v - 1);
    }
  }

  let best = stuck.size;
  for (let lang = 1; lang <= n; lang++) {
    let teach = 0;
    for (const user of stuck) {
      if (!known[user].has(lang)) {
        teach++;
      }
    }
    best = Math.min(best, teach);
  }
  return best;
}

