function minimumTeachings(n, languages, friendships) {
  // For each language, walk the friendships and mark who would have to learn it.
  let answer = Infinity;
  for (let L = 1; L <= n; L++) {
    const taught = new Array(languages.length).fill(false);
    for (const [u, v] of friendships) {
      const a = languages[u - 1], b = languages[v - 1];
      if (a.some(x => b.includes(x))) continue;
      if (!a.includes(L)) taught[u - 1] = true;
      if (!b.includes(L)) taught[v - 1] = true;
    }
    answer = Math.min(answer, taught.filter(Boolean).length);
  }
  return answer;
}

