function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 301) : 2 + Math.floor(rand() * 4);
  const m = large ? 500 : 2 + Math.floor(rand() * 6);
  const most = large ? (rand() < 0.5 ? 4 : 30) : Math.min(n, 3);
  // Popular languages make sharing common, so both stuck and fine friendships appear.
  const popular = large ? 8 : n;
  const pick = () => 1 + Math.floor(rand() * (rand() < 0.6 ? popular : n));
  const languages = [];
  for (let i = 0; i < m; i++) {
    const want = 1 + Math.floor(rand() * most);
    const set = new Set();
    for (let t = 0; t < want * 3 && set.size < want; t++) set.add(pick());
    languages.push([...set]);
  }
  const pairs = m * (m - 1) / 2;
  const count = large ? 500 : 1 + Math.floor(rand() * Math.min(8, pairs));
  const seen = new Set();
  const friendships = [];
  while (friendships.length < count) {
    const a = 1 + Math.floor(rand() * m), b = 1 + Math.floor(rand() * m);
    if (a === b) continue;
    const u = Math.min(a, b), v = Math.max(a, b);
    if (seen.has(u * 1000 + v)) continue;
    seen.add(u * 1000 + v);
    friendships.push([u, v]);
  }
  return [n, languages, friendships];
}
